ALTER TABLE "orders" DROP CONSTRAINT "orders_valid";--> statement-breakpoint
CREATE INDEX "orders_channel_created_idx" ON "orders" USING btree ("channel","created_at","id");--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_valid" CHECK ("orders"."status" IN ('pending','awaiting_confirmation','confirmed','ready_for_pickup','out_for_delivery','fulfilled','cancelled') AND "orders"."payment_status" IN ('unpaid','paid','refunded') AND "orders"."fulfillment_method" IN ('delivery','pickup') AND ("orders"."pickup_payment" IS NULL OR "orders"."pickup_payment" IN ('online','upon_pickup')) AND ("orders"."status" <> 'fulfilled' OR "orders"."payment_status" = 'paid') AND ("orders"."status" <> 'cancelled' OR "orders"."payment_status" <> 'paid') AND "orders"."subtotal" >= 0 AND "orders"."discount" >= 0 AND "orders"."discount" <= "orders"."subtotal" AND "orders"."shipping_fee" >= 0 AND "orders"."total" = "orders"."subtotal" - "orders"."discount" + "orders"."shipping_fee" AND "orders"."channel" IN ('ecommerce','pos') AND ("orders"."channel" <> 'pos' OR ("orders"."customer_id" IS NULL AND "orders"."actor_id" IS NOT NULL AND "orders"."status" = 'fulfilled' AND "orders"."payment_status" = 'paid' AND "orders"."payment_method" IS NOT NULL AND "orders"."amount_tendered" IS NOT NULL)) AND ("orders"."payment_method" IS NULL OR "orders"."payment_method" IN ('cash','gcash','card','bank_transfer')) AND "orders"."change_due" >= 0 AND ("orders"."amount_tendered" IS NULL OR "orders"."amount_tendered" >= "orders"."total"));